<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_role('admin');$pageTitle='Student Management | StudentHub';$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';if($action==='add'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$course=trim($_POST['course']??'Computer Engineering');$sem=(int)($_POST['semester']??3);if(strlen($name)>1&&filter_var($email,FILTER_VALIDATE_EMAIL)){$s=$conn->prepare('INSERT INTO students(name,email,course,semester) VALUES(?,?,?,?)');$s->bind_param('sssi',$name,$email,$course,$sem);$notice=$s->execute()?'Student added.':'Could not add student (email may already exist).';$s->close();audit($conn,'student.add',$email);}else $notice='Enter a valid name and email.';}elseif($action==='delete'){$id=(int)($_POST['id']??0);$s=$conn->prepare('DELETE FROM students WHERE id=?');$s->bind_param('i',$id);$s->execute();$notice='Delete request processed.';$s->close();audit($conn,'student.delete','Student id '.$id);}}
$q=trim($_GET['q']??'');$like='%'.$q.'%';$s=$conn->prepare('SELECT id,name,email,course,semester FROM students WHERE name LIKE ? OR email LIKE ? OR course LIKE ? ORDER BY id DESC');$s->bind_param('sss',$like,$like,$like);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();require __DIR__.'/../includes/header.php'; ?><h1>Student management</h1><?php if($notice): ?><p class="notice"><?= e($notice) ?></p><?php endif; ?><form class="toolbar" method="get"><label for="q">Search</label><input id="q" name="q" value="<?= e($q) ?>" placeholder="Name, email or course"><button class="button">Search</button></form><div class="grid two"><form class="form" method="post"><h2>Add student</h2><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Course</label><input name="course" value="Computer Engineering" required></div><div class="field"><label>Semester</label><input name="semester" type="number" min="1" max="8" value="3" required></div><button class="button">Add student</button></form><div><h2>Student records</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Course</th><th>Semester</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= e($r['name']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['course']) ?></td><td><?= (int)$r['semester'] ?></td><td><form method="post" onsubmit="return confirm('Delete this student?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button>Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
